  ["1e4f9b0c156fdb79"] = { "Bene, hai del fegato! Mi piace. Allora, andiamo!", "." },
  ["1e5063265ce02ed3"] = { "%s fruga tra i rifiuti.", "." },
  ["1e51730bcf206c45"] = { "Gli umani hanno davvero bisogno di tutto il nostro aiuto nel ⟦Arathi Basin=Bacino d'Arathi⟧. Quello con cui devi parlare si chiama ⟦Keras Wolfheart=Keras Cuordilupo⟧. Ti aspetta, pronto ad aiutarti, sulla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧.", "." },
  ["1e583a623ec5fc47"] = { "Purificati!", "." },
