  ["1e8ed1a26f9abb0e"] = { "Metto a tua disposizione tutto l'aiuto che posso offrirti.", "." },
  ["1e99e373e0f09817"] = { "Sai dove posso trovare il ⟦Half Pendant of Aquatic Endurance=Mezzo Pendente della Resistenza Acquatica⟧?", "." },
  ["1e9aaf46c26afe6d"] = { "Se cerchi armature a piastre, armature di maglia o scudi, ho i migliori di tutta ⟦Undercity=Sepulcra⟧. La maggior parte di questi pezzi è fatta e riparata qui, anche se alcuni sono di recupero.\n\nDai pure un'occhiata.", "." },
  ["1ea589a5f55114ce"] = { "Sì? Sì? Che c'è?\n\nI Reietti hanno di certo un appetito enorme. Fa' come se fossi a casa tua... sì, riposa quelle ossa stanche. Mi chiamo Renee, se ti serve qualcosa.", "." },
  ["1ea910a1213c2f6f"] = { "Ti attende la prossima scelta.\n\nHai giurato di servire come boia il tuo signore. Un uomo ti viene consegnato perché sia giustiziato come traditore del tuo signore e del tuo popolo. Conosci quest'uomo: un amico intimo e virtuoso, sparito misteriosamente un giorno. Sai anche che i crimini per cui è stato condannato avrebbero causato la morte di molti civili innocenti. Quando ti vede, implora pietà, sostenendo di essere stato incastrato da un'autorità superiore.\n\nFai la tua scelta.", "." },
  ["1eac6ed903b236ca"] = { "Tenevo da parte questo posto per qualcosa di speciale. Non credo che ci sia niente di più speciale di questo, {name}.", "." },
